<script setup>
import {extRows,extStatus,demandBalance} from './payment-schedules.js';
import {ref,computed} from 'vue';import {can,fieldAccess,money,cents,effective} from './domain.js';import {dashboardSummary} from './dashboard.js';import {suiteRows,orderStatus,suiteFields} from './vendor-suite.js';import MetricChart from './MetricChart.vue';import MetaFields from './MetaFields.vue';
const props=defineProps(['state','user','tenantId','execute','busy','failure']);const dialog=ref(''),form=ref({}),formRef=ref(null),error=ref(''),tab=ref('progress'),month=ref(new Date().toISOString().slice(0,7));const today=()=>new Date().toISOString().slice(0,10);const d=computed(()=>(props.state.dashboards||dashboardSummary(props.state,props.user)).find(d=>d.tenantId===props.tenantId)||{});const records=k=>suiteRows(props.state,k,props.tenantId);const plan=computed(()=>records('project_plan').at(-1));const editable=k=>can(props.state,props.user,props.tenantId,'create',k)&&suiteFields[k].every(f=>fieldAccess(props.state,props.user,props.tenantId,f,k)==='edit');const period=computed(()=>d.value.cashMonths?.find(r=>r.month===month.value)||{actual:0,target:0});const budgetPercent=computed(()=>d.value.budget?.target?Math.round(d.value.budget.committed/d.value.budget.target*100):0);const currentOrders=computed(()=>props.state.orders.filter(o=>o.tenantId===props.tenantId&&orderStatus(props.state,o)==='Approved'));const booked=computed(()=>records('sale').filter(s=>s.status==='Booked'));const req=v=>!!String(v??'').trim()||'Required';const latest=(id)=>records('progress').filter(p=>p.orderId===id).sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt)).at(-1);const who=id=>props.state.users.find(u=>u.id===id)?.name||'Project user';
function open(k,s){error.value='';dialog.value=k;if(k==='project_plan'){form.value={budgetPrice:String((plan.value?.budget||0)/100),salesPrice:String((plan.value?.salesTarget||0)/100),unitTarget:plan.value?.unitTarget||0,startDate:plan.value?.startDate||today(),endDate:plan.value?.endDate||today(),monthlyTargets:plan.value?.monthlyTargets?.map(x=>({...x,price:String(x.cash/100)}))||[{month:month.value,price:'',progress:0}],data:{}};}if(k==='progress')form.value={orderId:'',percent:0,date:today(),comments:'',data:{}};if(k==='sale')form.value=s?{...JSON.parse(JSON.stringify(s)),price:String(s.amount/100)}:{unit:'',customer:'',status:'Lead',price:'',date:today(),data:{}};if(k==='collection')form.value={saleId:'',price:'',tdsPrice:'0',mode:'NEFT',bank:'',date:today(),reference:'',remarks:'',data:{}};}
async function save(){try{error.value='';if(formRef.value&&!(await formRef.value.validate()).valid)return;const x={...form.value,recordKind:dialog.value};if(dialog.value==='project_plan'){x.budget=cents(x.budgetPrice);x.salesTarget=cents(x.salesPrice);x.unitTarget=Number(x.unitTarget);x.monthlyTargets=x.monthlyTargets.map(t=>({month:t.month,cash:cents(t.price),progress:Number(t.progress)}));}else if(dialog.value==='progress')x.percent=Number(x.percent);else x.amount=cents(x.price);if(dialog.value==='collection')x.tds=cents(x.tdsPrice);const r=await props.execute('suite-save',x,'Project record saved',false);if(r)dialog.value='';}catch(e){error.value=e.message;}}
const cashSeries=[{key:'target',label:'Target'},{key:'actual',label:'Collected'}],progressSeries=[{key:'planned',label:'Planned'},{key:'actual',label:'Measured'}];
</script>
<template>
<div class="dashboard-controls"><div><span class="eyebrow">PROJECT PULSE</span><p class="small muted mt-2">Live rollups of recorded progress, collections, sales and approved commitments.</p></div><div class="heading-actions"><v-btn v-if="editable('project_plan')" variant="outlined" prepend-icon="mdi-tune" @click="open('project_plan')">Budget & targets</v-btn><v-btn v-if="editable('progress')" variant="outlined" @click="open('progress')">Update progress</v-btn><v-btn v-if="editable('sale')" variant="outlined" @click="open('sale')">Add sale</v-btn><v-btn v-if="editable('collection')" color="primary" @click="open('collection')">Record collection</v-btn></div></div>
<div class="stats-grid mt-6"><div v-if="d.progress!=null" class="stat-card primary-stat"><div class="stat-label">Work progress</div><strong>{{d.progress}}%</strong><span>Weighted by approved work-order values</span></div><div v-if="d.cashMonths" class="stat-card"><div class="stat-label">Cash collected · {{month}}</div><strong>{{money(period.actual)}}</strong><span>Target {{money(period.target)}} · {{period.target?Math.round(period.actual/period.target*100)+'% achieved':'target not set'}}</span></div><div v-if="d.sales" class="stat-card"><div class="stat-label">Booked sales value</div><strong>{{money(d.sales.bookedValue)}}</strong><span>{{d.sales.stages.Booked}} booked units · target {{d.sales.unitTarget||'not set'}}</span></div><div v-if="d.budget" class="stat-card"><div class="stat-label">Budget committed</div><strong>{{budgetPercent}}%</strong><span>{{money(d.budget.committed)}} of {{money(d.budget.target)}}</span></div></div>
<section v-if="can(state,user,tenantId,'view','demand')&amp;&amp;fieldAccess(state,user,tenantId,'amount','demand')!=='hidden'" class="panel mb-6"><div class="panel-top"><h2>Customer payment demands</h2><span class="quiet-label">See Payment schedules &amp; demands for approvals and receipts</span></div><div class="detail-content"><div class="form-two-columns"><div><small>Issued balance</small><h3>{{money(extRows(state,'demand',tenantId).filter(d=>extStatus(state,d)==='Approved').reduce((n,d)=>n+demandBalance(state,d),0))}}</h3></div><div><small>Overdue balance</small><h3>{{money(extRows(state,'demand',tenantId).filter(d=>extStatus(state,d)==='Approved'&amp;&amp;d.dueDate&lt;today()).reduce((n,d)=>n+demandBalance(state,d),0))}}</h3></div></div></div></section><div class="insights-grid"><article v-if="d.cashMonths" class="insight-card"><v-icon color="primary">mdi-cash-clock</v-icon><div><strong>{{period.target?period.actual<period.target?'Collection shortfall '+money(period.target-period.actual):'Collection target achieved':'Set a monthly cash target'}}</strong><p>{{period.target?'For '+month+'. Total project collections: '+money(d.collected):'Add targets to compare receipts against your plan.'}}</p></div></article><article v-if="d.budget" class="insight-card"><v-icon color="primary">mdi-wallet-outline</v-icon><div><strong>{{d.budget.remaining<0?'Over budget by '+money(-d.budget.remaining):'Available budget '+money(d.budget.remaining)}}</strong><p>Pending work orders and expenses are excluded; payments do not add cost again.</p></div></article><article v-if="d.sales" class="insight-card"><v-icon color="primary">mdi-home-city-outline</v-icon><div><strong>{{d.sales.stages.Reserved}} reserved · {{d.sales.stages.Lead}} leads</strong><p>{{d.sales.target?'Booked value is '+Math.round(d.sales.bookedValue/d.sales.target*100)+'% of the sales-value target.':'Set a sales-value target to track attainment.'}}</p></div></article></div>
<div class="lower-grid"><section v-if="d.cashMonths" class="panel"><div class="panel-top"><h2>Cash inflows vs target</h2><v-select v-model="month" :items="d.cashMonths.map(r=>r.month)" label="Insight month" hide-details density="compact" class="vendor-picker"/></div><MetricChart :rows="d.cashMonths" :series="cashSeries" title="Monthly cash collections compared with targets in lakh rupees"/></section><section v-if="d.progressMonths" class="panel"><div class="panel-top"><div><h2>Work progress vs plan</h2><p>Last saved measurements within each period.</p></div></div><MetricChart :rows="d.progressMonths" :series="progressSeries" title="Planned and measured project completion percentages" percent/></section><section v-if="d.budget" class="panel"><div class="panel-top"><h2>Budget tracking</h2></div><MetricChart :rows="[{label:'Budget',value:d.budget.target},{label:'WOs',value:d.budget.workOrders},{label:'POs',value:d.budget.purchases},{label:'Expenses',value:d.budget.additional},{label:'Committed',value:d.budget.committed}]" :series="[{key:'value',label:'Value including tax'}]" title="Project target and approved cost components in lakh rupees"/><div class="table-bottom">Net recorded payments {{money(d.budget.paid)}} · TDS {{money(d.budget.tds)}}</div></section><section v-if="d.sales" class="panel"><div class="panel-top"><h2>Sales insights</h2></div><div class="sales-stage-grid"><div v-for="(n,k) in d.sales.stages" :key="k"><strong>{{n}}</strong><span>{{k}}</span></div></div><table class="orders-table"><tbody><tr><td>Booked value</td><td>{{money(d.sales.bookedValue)}}</td></tr><tr><td>Sales-value target</td><td>{{money(d.sales.target)}}</td></tr><tr><td>Unit booking target</td><td>{{d.sales.unitTarget}}</td></tr><tr><td>Bookings / active opportunities</td><td>{{Math.round(d.sales.stages.Booked/Math.max(1,d.sales.stages.Lead+d.sales.stages.Reserved+d.sales.stages.Booked)*100)}}%</td></tr></tbody></table></section></div>
<section class="panel mt-6"><div class="panel-top"><h2>Project records</h2><span class="quiet-label">Custom fields are managed in Form configuration.</span></div><v-tabs v-model="tab" color="primary"><v-tab value="progress">Work progress</v-tab><v-tab v-if="records('sale').length||editable('sale')" value="sales">Unit sales</v-tab><v-tab v-if="records('collection').length||editable('collection')" value="collections">Collections</v-tab><v-tab v-if="records('project_plan').length" value="plans">Budget history</v-tab></v-tabs><div class="table-scroll"><table class="orders-table"><template v-if="tab==='progress'"><thead><tr><th>WORK ORDER</th><th>MEASURED PROGRESS</th><th>LAST UPDATE</th><th>NOTE</th></tr></thead><tbody><tr v-for="o in currentOrders" :key="o.id"><td>{{o.number}}<span class="cell-secondary">{{o.description}}</span></td><td>{{latest(o.id)?.percent??'Not recorded'}}{{latest(o.id)?'%':''}}<v-progress-linear v-if="latest(o.id)" :model-value="latest(o.id).percent" color="primary" class="mt-2" rounded/></td><td>{{latest(o.id)?.date||'—'}}</td><td class="scope-cell">{{latest(o.id)?.comments||'—'}}<div v-for="(v,k) in latest(o.id)?.data" :key="k" class="cell-secondary">{{k}}: {{v}}</div></td></tr></tbody></template><template v-if="tab==='sales'"><thead><tr><th>UNIT / CUSTOMER</th><th>STAGE</th><th>VALUE</th><th>DATE</th><th></th></tr></thead><tbody><tr v-for="s in records('sale')" :key="s.id"><td>{{s.unit||'Restricted'}}<span class="cell-secondary">{{s.customer||'Restricted'}}</span></td><td>{{s.status||'Restricted'}}</td><td>{{money(s.amount)}}</td><td>{{s.date||'Restricted'}}</td><td><v-btn v-if="editable('sale')&&(user.superuser||s.createdBy===user.id)" variant="text" size="small" @click="open('sale',s)">Edit sale</v-btn><div v-for="(v,k) in s.data" :key="k" class="cell-secondary">{{k}}: {{v}}</div></td></tr></tbody></template><template v-if="tab==='collections'"><thead><tr><th>RECEIPT / UNIT</th><th>DATE</th><th>COLLECTED</th><th>REMARKS</th><th>RECORDED BY</th></tr></thead><tbody><tr v-for="r in records('collection').slice().reverse()" :key="r.id"><td>{{r.reference||'Restricted'}}<span class="cell-secondary">{{records('sale').find(s=>s.id===r.saleId)?.unit||'Restricted'}}</span></td><td>{{r.date||'Restricted'}}</td><td>{{money(r.amount)}}</td><td>{{r.remarks||'—'}}<div v-for="(v,k) in r.data" :key="k" class="cell-secondary">{{k}}: {{v}}</div></td><td>{{who(r.createdBy)}}</td></tr></tbody></template><template v-if="tab==='plans'"><thead><tr><th>VERSION DATE</th><th>BUDGET TARGET</th><th>SALES TARGET</th><th>PROJECT PERIOD</th><th>SET BY</th></tr></thead><tbody><tr v-for="p in records('project_plan').slice().reverse()" :key="p.id"><td>{{new Date(p.createdAt).toLocaleString('en-IN')}}</td><td>{{money(p.budget)}}</td><td>{{money(p.salesTarget)}}</td><td>{{p.startDate||'Restricted'}} · {{p.endDate||'Restricted'}}</td><td>{{who(p.createdBy)}}<div v-for="(v,k) in p.data" :key="k" class="cell-secondary">{{k}}: {{v}}</div></td></tr></tbody></template></table></div></section>
<section v-if="d.budget" class="panel mt-6"><div class="panel-top"><div><h2>Work orders → approved commitments</h2><p>Approved work orders allocate {{money(d.budget.workOrders)}} of the separate project budget.</p></div></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>WORK ORDER / QUOTATION</th><th>CONTRACT</th><th>COMMITTED VALUE</th></tr></thead><tbody><tr v-for="o in currentOrders" :key="o.id"><td>{{o.number}}<span class="cell-secondary">{{o.quotationNumber||'Legacy · quotation not recorded'}}</span></td><td>{{o.contractType||'Legacy · type not recorded'}}</td><td>{{money(effective(state,o))}}</td></tr></tbody></table></div></section>
<v-alert v-if="failure" type="error" class="mt-5">{{failure}}</v-alert><v-dialog :model-value="!!dialog" @update:model-value="v=>{if(!v)dialog=''}" max-width="850"><v-card><v-card-title class="dialog-title">{{dialog==='project_plan'?'Project budget & targets':dialog==='progress'?'Record work progress':dialog==='sale'?'Unit sales record':'Record cash collection'}}<v-btn icon="mdi-close" variant="text" aria-label="Close form" @click="dialog=''"/></v-card-title><v-card-text><v-alert v-if="error||failure" type="error" class="mb-4">{{error||failure}}</v-alert><v-form ref="formRef" @submit.prevent="save"><template v-if="dialog==='project_plan'"><div class="form-two-columns"><v-text-field v-model="form.budgetPrice" label="Project budget target (₹) *" :rules="[req]"/><v-text-field v-model="form.salesPrice" label="Sales-value target (₹) *" :rules="[req]"/><v-text-field v-model="form.unitTarget" label="Booked-unit target *" type="number"/><v-text-field v-model="form.startDate" label="Project start *" type="date"/><v-text-field v-model="form.endDate" label="Project end *" type="date"/></div><p class="config-heading">Monthly cash and progress targets</p><div v-for="(x,i) in form.monthlyTargets" :key="i" class="purchase-line"><div class="form-two-columns"><v-text-field v-model="x.month" type="month" label="Month *"/><v-text-field v-model="x.price" inputmode="decimal" label="Cash target (₹) *"/><v-text-field v-model="x.progress" type="number" min="0" max="100" label="Planned completion (%) *"/><v-btn variant="text" color="error" @click="form.monthlyTargets.splice(i,1)">Remove month</v-btn></div></div><v-btn variant="outlined" @click="form.monthlyTargets.push({month:'',price:'0',progress:0})">Add month</v-btn><p class="small muted mt-4">Saving creates a retained target version. It does not rewrite earlier targets.</p></template><template v-if="dialog==='progress'"><v-select v-model="form.orderId" :items="currentOrders.map(o=>({title:o.number+' · '+o.description,value:o.id}))" label="Approved work order *" :rules="[req]"/><v-text-field v-model="form.percent" type="number" min="0" max="100" label="Measured completion (%) *"/><v-text-field v-model="form.date" type="date" label="Measurement date *"/><v-textarea v-model="form.comments" label="Measurement note *" :rules="[req]" rows="3"/></template><template v-if="dialog==='sale'"><div class="form-two-columns"><v-text-field v-model="form.unit" label="Unit reference *" :rules="[req]"/><v-text-field v-model="form.customer" label="Customer name *" :rules="[req]"/><v-select v-model="form.status" :items="['Lead','Reserved','Booked','Cancelled']" label="Sales stage *"/><v-text-field v-model="form.date" type="date" label="Sales date *"/></div><v-text-field v-model="form.price" label="Unit value including tax (₹) *" inputmode="decimal" :rules="[req]"/></template><template v-if="dialog==='collection'"><v-select v-model="form.saleId" :items="booked.map(s=>({title:s.unit+' · '+s.customer,value:s.id}))" label="Booked unit *" :rules="[req]"/><v-text-field v-model="form.reference" label="Receipt reference *" :rules="[req]"/><div class="form-two-columns"><v-text-field v-model="form.tdsPrice" label="TDS deducted (₹)" inputmode="decimal"/><v-select v-model="form.mode" :items="['Cheque','RTGS','NEFT','UPI','Cash','Other']" label="Payment mode"/><v-text-field v-model="form.bank" label="Bank"/><v-text-field v-model="form.price" label="Net cash received (₹) *" inputmode="decimal" :rules="[req]"/><v-text-field v-model="form.date" type="date" label="Received date *"/></div><v-textarea v-model="form.remarks" label="Remarks" rows="2"/><p class="small muted">Record confirmed receipts. Total collections cannot exceed the booked unit value.</p></template><MetaFields v-if="dialog" :state="state" :user="user" :tenant-id="tenantId" :form-id="dialog" :record="form"/></v-form></v-card-text><v-card-actions class="dialog-actions"><v-btn @click="dialog=''">Cancel</v-btn><v-spacer/><v-btn color="primary" :loading="busy" @click="save">{{dialog==='project_plan'?'Save target version':'Save record'}}</v-btn></v-card-actions></v-card></v-dialog>
</template>
